import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA/C++ source for a fused Linear + Sigmoid + Sum kernel
fused_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_linear_sigmoid_sum_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ out,
    int batch_size,
    int input_size,
    int hidden_size
){
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < batch_size) {
        float sumVal = 0.0f;
        for (int j = 0; j < hidden_size; j++) {
            float tmp = 0.0f;
            // Compute the linear operation for x[i] * weight[j] + bias[j]
            for (int k = 0; k < input_size; k++){
                tmp += x[i * input_size + k] * weight[j * input_size + k];
            }
            tmp += bias[j];
            // Sigmoid
            float s = 1.0f / (1.0f + expf(-tmp));
            // Accumulate into sum
            sumVal += s;
        }
        out[i] = sumVal;
    }
}

torch::Tensor fused_linear_sigmoid_sum(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    // x shape: (batch_size, input_size)
    // weight shape: (hidden_size, input_size)
    // bias shape: (hidden_size)
    // output shape: (batch_size)
    int batch_size = x.size(0);
    int input_size = x.size(1);
    int hidden_size = weight.size(0);

    auto out = torch::zeros({batch_size}, x.options());

    const int block_size = 256;
    const int grid_size = (batch_size + block_size - 1) / block_size;

    fused_linear_sigmoid_sum_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        out.data_ptr<float>(),
        batch_size,
        input_size,
        hidden_size
    );

    return out;
}
""".strip()

fused_cpp_source = "torch::Tensor fused_linear_sigmoid_sum(torch::Tensor x, torch::Tensor weight, torch::Tensor bias);"

# Build the fused kernel extension
fused_module = load_inline(
    name="fused_linear_sigmoid_sum",
    cpp_sources=fused_cpp_source,
    cuda_sources=fused_source,
    functions=["fused_linear_sigmoid_sum"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized model that fuses matrix multiplication, sigmoid, and sum into a custom CUDA kernel.
    """
    def __init__(self, input_size, hidden_size):
        super().__init__()
        # Parameters matching the original linear layer
        self.weight = nn.Parameter(torch.randn(hidden_size, input_size))
        self.bias = nn.Parameter(torch.randn(hidden_size))

    def forward(self, x):
        # Call the fused kernel
        out = fused_module.fused_linear_sigmoid_sum(x, self.weight, self.bias)
        # Reshape to (batch_size, 1)
        return out.view(-1, 1)

